    ('constants', '"""Engine constants mirrored from kaggle_environments.envs.kaggriculture.\n\nHand-copied on purpose: the submission must not import kaggle_environments\ninternals. tests/test_econ_parity.py keeps these honest against the installed\nengine.\n"""\n\nCROPS = {\n    "WHEAT":      {"seed": 10,  "first_yield_day": 2,  "max_yield_day": 4,  "interval": 0, "max_yield": 6, "ongoing": False},\n    "CARROT":     {"seed": 20,  "first_yield_day": 2,  "max_yield_day": 3,  "interval": 0, "max_yield": 4, "ongoing": False},\n    "TOMATO":     {"seed": 50,  "first_yield_day": 8,  "max_yield_day": 8,  "interval": 1, "max_yield": 4, "ongoing": True},\n    "STRAWBERRY": {"seed": 100, "first_yield_day": 10, "max_yield_day": 10, "interval": 2, "max_yield": 4, "ongoing": True},\n    "MELON":      {"seed": 80,  "first_yield_day": 10, "max_yield_day": 12, "interval": 0, "max_yield": 6, "ongoing": False},\n}\n\nANIMALS = {\n    "GOOSE": {"cost": 300, "structure": "COOP",    "first_yield_day": 4, "interval": 1, "max_held": 4, "product": "EGG"},\n    "COW":   {"cost": 400, "structure": "PASTURE", "first_yield_day": 8, "interval": 2, "max_held": 6, "product": "MILK"},\n    "SHEEP": {"cost": 500, "structure": "PASTURE", "first_yield_day": 6, "interval": 3, "max_held": 6, "product": "WOOL"},\n}\n\nPRODUCTS = ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK", "WOOL", "FERTILIZER"]\n\nMARKET_I0 = 10000\nPRICE_FLOOR = 1\nHINGE_GAIN = 8.0\n\nMARKET_PARAMS = {\n    "WHEAT":      {"base":  25, "I0": MARKET_I0, "T": 400, "below_func": "sqrt",   "below_target": 0.80, "above_func": "log",    "above_target": 0.20},\n    "CARROT":     {"base":  35, "I0": MARKET_I0, "T": 450, "below_func": "hinge",  "below_target": 1.00, "above_func": "sqrt",   "above_target": 0.70},\n    "TOMATO":     {"base":  60, "I0": MARKET_I0, "T": 200, "below_func": "hinge",  "below_target": 0.40, "above_func": "sqrt",   "above_target": 0.60},\n    "STRAWBERRY": {"base": 120, "I0": MARKET_I0, "T": 100, "below_func": "sqrt",   "below_target": 0.70, "above_func": "linear", "above_target": 1.60},\n    "MELON":      {"base": 250, "I0": MARKET_I0, "T": 300, "below_func": "log",    "below_target": 0.20, "above_func": "sq",     "above_target": 3.60},\n    "EGG":        {"base":  50, "I0": MARKET_I0, "T": 332, "below_func": "hinge",  "below_target": 0.40, "above_func": "log",    "above_target": 0.20},\n    "MILK":       {"base": 160, "I0": MARKET_I0, "T": 122, "below_func": "sqrt",   "below_target": 0.60, "above_func": "linear", "above_target": 1.60},\n    "WOOL":       {"base": 200, "I0": MARKET_I0, "T": 105, "below_func": "log",    "below_target": 0.20, "above_func": "sq",     "above_target": 3.20},\n    "FERTILIZER": {"base": 100, "I0": MARKET_I0, "T": 200, "below_func": "linear", "below_target": 0.40, "above_func": "linear", "above_target": 0.40},\n}\n\nSHOPS = {\n    "BAKERY":         ["EGG", "WHEAT"],\n    "PIZZA_SHOP":     ["MILK", "TOMATO", "WHEAT"],\n    "BRUNCH_SPOT":    ["EGG", "WHEAT", "STRAWBERRY"],\n    "YARN_STORE":     ["WOOL"],\n    "ICE_CREAM_SHOP": ["STRAWBERRY", "MILK", "WHEAT"],\n    "PET_CAFE":       ["CARROT"],\n    "SMOOTHIE_SHOP":  ["STRAWBERRY", "MILK"],\n    "FARMERS_MARKET": ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY"],\n}\n\nTOWN_CENTER_PRODUCTS = [p for p in PRODUCTS if p != "FERTILIZER"]\nMAX_SHOP_INSTANCES = 8\n\nLAND_ORDER = ["NE", "SW", "SE"]\nLAND_PRICES = [1000, 2000, 4000]\nFARM_HAND_COST_MULT = 1\n\n# Default configuration values (kaggriculture.json).\nTURNS_PER_DAY = 24\nEPISODE_STEPS = 720\nBOARD_SIZE = 10\nSHED_CAPACITY = 100\nMAX_MARKET_ORDERS = 10\nTOWN_SHOP_UNLOCK_INTERVAL = 3   # days\nTOWN_SHOP_SELL_INTERVAL = 4     # turns\nTOWN_CENTER_SELL_INTERVAL = 24  # turns\n\n# Board geometry at boardSize 10.\nSHED_ACCESS = [(4, 4), (5, 4), (4, 5), (5, 5)]  # NWSE order; shed ops work even on LOCKED ones\nSPAWN = (4, 4)\n\nMOVES = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}\n\n# Buyable back from the market via BUY_PRODUCT.\nBUYABLE_PRODUCTS = ("WHEAT", "FERTILIZER")\n\n_FIB_CACHE = [1, 1]\n\n\ndef fib(n):\n    """fib(0)=1, fib(1)=1, fib(2)=2 ... (engine\'s _fib)."""\n    while len(_FIB_CACHE) <= n:\n        _FIB_CACHE.append(_FIB_CACHE[-1] + _FIB_CACHE[-2])\n    return _FIB_CACHE[n]\n'),
    ('econ', '"""Pure economic model: exact mirror of the engine\'s price function plus\nmarginal-revenue helpers. No state, stdlib only.\n"""\n\nimport math\n\n\n\ndef _shape(func, x, T=None):\n    x = max(0.0, x)\n    if func == "linear":\n        return x\n    if func == "sq":\n        return x * x\n    if func == "sqrt":\n        return math.sqrt(x)\n    if func == "log":\n        return math.log(1.0 + x)\n    if func == "log10":\n        return math.log10(1.0 + x)\n    if func == "hinge":\n        if not T or T <= 0:\n            return x\n        u = x / T\n        return u + HINGE_GAIN * max(0.0, u - 1.0) ** 2\n    return x\n\n\ndef price(item, inventory):\n    """Engine market_price: price at a given market inventory level."""\n    p = MARKET_PARAMS[item]\n    base = p["base"]\n    I0 = p["I0"]\n    T = p["T"]\n    if inventory < I0:\n        f = p["below_func"]\n        amp = p["below_target"] * base / _shape(f, T, T)\n        val = base + amp * _shape(f, I0 - inventory, T)\n    else:\n        f = p["above_func"]\n        amp = p["above_target"] * base / _shape(f, T, T)\n        val = base - amp * _shape(f, inventory - I0, T)\n    return max(PRICE_FLOOR, int(round(val)))\n\n\ndef sell_marginal_prices(item, inventory, n):\n    """Prices received for units 1..n of a solo sell starting at `inventory`.\n\n    Engine quotes each unit at pre-sell inventory, then increments inventory\n    only if the unit sold above the $1 floor.\n    """\n    out = []\n    inv = inventory\n    for _ in range(n):\n        p = price(item, inv)\n        out.append(p)\n        if p > PRICE_FLOOR:\n            inv += 1\n    return out\n\n\ndef sell_revenue(item, inventory, n):\n    return sum(sell_marginal_prices(item, inventory, n))\n\n\ndef units_sellable_above(item, inventory, min_price, cap=10_000):\n    """How many units can be sold, one at a time, before the marginal price\n    drops below `min_price`."""\n    count = 0\n    inv = inventory\n    while count < cap:\n        p = price(item, inv)\n        if p < min_price:\n            break\n        count += 1\n        if p > PRICE_FLOOR:\n            inv += 1\n    return count\n\n\ndef buy_cost(item, inventory, n):\n    """Cost of BUY_PRODUCT for n units. Engine quotes each unit at the\n    post-buy inventory (inv - 1), then decrements."""\n    total = 0\n    inv = inventory\n    for _ in range(n):\n        total += price(item, inv - 1)\n        inv -= 1\n    return total\n\n\ndef town_drain_per_day(unlocked_shops):\n    """Expected market-inventory drain per item per day from town buildings.\n\n    Shops tick every TOWN_SHOP_SELL_INTERVAL turns (single-product shops\n    consume 2x); the town center ticks every TOWN_CENTER_SELL_INTERVAL turns.\n    """\n    shop_ticks = TURNS_PER_DAY / TOWN_SHOP_SELL_INTERVAL\n    center_ticks = TURNS_PER_DAY / TOWN_CENTER_SELL_INTERVAL\n    drain = {}\n    for item in TOWN_CENTER_PRODUCTS:\n        drain[item] = center_ticks\n    for shop in unlocked_shops:\n        items = SHOPS.get(shop, ())\n        mult = 2 if len(items) == 1 else 1\n        for item in items:\n            drain[item] = drain.get(item, 0.0) + mult * shop_ticks\n    return drain\n\n\ndef hire_marginal_cost(hires_today):\n    """Cost of the next HIRE given hires already made today."""\n    return FARM_HAND_COST_MULT * fib(hires_today)\n\n\ndef hire_total_cost(k):\n    """Total cost of hiring k hands in one day: fib(k+1) - 1."""\n    return sum(fib(i) for i in range(k))\n'),
    ('gamestate', '"""Per-turn observation parsing (View) and episode-persistent state (Memory)."""\n\n\n\nclass FarmView:\n    __slots__ = ("money", "tiles", "units", "unlocked_quadrants", "hires_today", "board_size")\n\n    def __init__(self, farm):\n        self.money = farm["money"]\n        self.tiles = farm["tiles"]  # tiles[y][x]\n        self.board_size = len(self.tiles)\n        fx, fy = farm["farmer"]\n        self.units = [(0, fx, fy)] + [\n            (i + 1, hx, hy) for i, (hx, hy) in enumerate(farm.get("hands", []))\n        ]\n        self.unlocked_quadrants = set(farm.get("unlocked_quadrants", ["NW"]))\n        self.hires_today = farm.get("hires_today", 0)\n\n    def tile(self, x, y):\n        return self.tiles[y][x]\n\n    def iter_tiles(self):\n        for y in range(self.board_size):\n            for x in range(self.board_size):\n                yield x, y, self.tiles[y][x]\n\n    def plants(self):\n        for x, y, t in self.iter_tiles():\n            if isinstance(t, dict) and t.get("kind") == "PLANT":\n                yield x, y, t\n\n    def animals(self):\n        """Occupied structures."""\n        for x, y, t in self.iter_tiles():\n            if isinstance(t, dict) and t.get("kind") in ("COOP", "PASTURE") and t.get("animal"):\n                yield x, y, t\n\n    def empty_structures(self):\n        for x, y, t in self.iter_tiles():\n            if isinstance(t, dict) and t.get("kind") in ("COOP", "PASTURE") and not t.get("animal"):\n                yield x, y, t\n\n    def weeds(self):\n        for x, y, t in self.iter_tiles():\n            if isinstance(t, dict) and t.get("kind") == "WEED":\n                yield x, y, t\n\n    def empty_tiles(self):\n        for x, y, t in self.iter_tiles():\n            if t is None:\n                yield x, y\n\n\nclass View:\n    def __init__(self, obs):\n        self.player = obs["player"]\n        self.step = obs.get("step", 0)\n        self.day = obs.get("day", self.step // TURNS_PER_DAY)\n        self.hour = obs.get("hour", self.step % TURNS_PER_DAY)\n        self.hours_left_today = TURNS_PER_DAY - self.hour  # includes this turn\n        # Last actable step is EPISODE_STEPS - 2 (718 by default).\n        self.steps_left = (EPISODE_STEPS - 2) - self.step\n\n        farms = obs["farms"]\n        self.me = FarmView(farms[self.player])\n        self.opp = FarmView(farms[1 - self.player])\n\n        private = obs.get("private", {}) or {}\n        self.shed = dict(private.get("shed", {}))\n        self.seeds = dict(private.get("seeds", {}))\n        self.unit_invs = [dict(inv) for inv in private.get("inventories", [{}])]\n        while len(self.unit_invs) < len(self.me.units):\n            self.unit_invs.append({})\n        self.shed_total = sum(self.shed.values())\n\n        market = obs.get("market", {}) or {}\n        self.market_inv = dict(market.get("inventory", {}))\n        self.market_prices = dict(market.get("prices", {}))\n        self.unlocked_shops = list((obs.get("town", {}) or {}).get("unlocked_shops", []))\n\n    def unit_inv(self, idx):\n        return self.unit_invs[idx] if idx < len(self.unit_invs) else {}\n\n\nclass Memory:\n    """Persists across steps within one episode (module globals survive).\n\n    Reset whenever step goes backwards (new episode reusing the process).\n    """\n\n    def __init__(self):\n        self.reset()\n\n    def reset(self):\n        self.last_step = -1\n        self.day_plan = None\n        self.day_plan_day = -1\n        self.prev_market_inv = None\n        self.my_sells_last_turn = {}\n        self.opp_sell_ema = {}\n        self.melons_sold = 0\n        self.timing_max_ms = 0.0\n\n    def observe(self, view):\n        if view.step <= self.last_step:\n            self.reset()\n        self.last_step = view.step\n'),
    ('planner', '"""Day-level strategic planner: quotas, hiring, land, sell floors."""\n\n\n# ---- Tunables (arena-calibrated) -------------------------------------------\n\n# Total melon units (ours + opponent\'s projected) the market absorbs at a good\n# price. Depth to $1 is 158; past ~120 the marginal price collapses.\nMELON_SUPPLY_TARGET = 140\nMELON_LAST_PLANT_DAY = 19       # d+10 harvest must land by day 29\nWHEAT_LAST_PLANT_DAY = 25\nCARROT_LAST_PLANT_DAY = 26\nTOMATO_LAST_PLANT_DAY = 18      # all 4 productions (ages 8-11) inside season\n\nGEESE_TARGET = 32\nGEESE_BUY_START_DAY = 2         # melon seeds soak day 0-1 cash; geese ride melon money\nGEESE_LAST_BUY_DAY = 24         # fertilizer pays from day 1, eggs from day 5\nGEESE_PER_DAY = 10\n\nWHEAT_TILE_CAP = 24             # rolling wheat engine (sale + feed)\nTOMATO_TILE_CAP = 12\nCARROT_TILE_CAP = 14\n\n# Hands to hire per day (index = day), before the workload/money gates.\nHIRE_SCHEDULE = [5, 6, 8, 10, 10, 12, 12, 12, 14, 14,\n                 14, 14, 14, 14, 14, 14, 14, 14, 14, 14,\n                 14, 14, 14, 12, 12, 12, 10, 10, 10, 8]\n\nLIQUIDATION_DAY = 27\nFINAL_STEP = 718                # last actable step at default config\n\n# Sell floors: marginal-revenue cutoffs. Cash compounds (geese, hires, land),\n# so holding stock for a slightly better price loses to reinvesting sooner.\nMELON_FLOOR = 80\nFERTILIZER_FLOOR = 50\nCARROT_FLOOR = 30\nTOMATO_FLOOR = 45\nFLOOR_DECAY_DAY = 24            # floors slide toward $1 from here to step 718\n\n\nclass DayPlan:\n    __slots__ = (\n        "hires_target", "land_buys", "plant_quota", "animal_buys",\n        "structure_builds", "sell_floors", "liquidation", "wheat_reserve",\n    )\n\n\ndef _count_crops(farm):\n    counts = {}\n    for _, _, t in farm.plants():\n        counts[t["crop"]] = counts.get(t["crop"], 0) + 1\n    return counts\n\n\ndef _projected_melons(farm):\n    """Units of melon this farm will plausibly bring to market from current tiles."""\n    total = 0\n    for _, _, t in farm.plants():\n        if t["crop"] == "MELON":\n            total += max(t.get("yield_units", 1), 4)  # assume decent care\n    return total\n\n\ndef make_day_plan(view, memory):\n    plan = DayPlan()\n    day = view.day\n    me = view.me\n    plan.liquidation = day >= LIQUIDATION_DAY\n\n    crops = _count_crops(me)\n    my_animals = sum(1 for _ in me.animals())\n    structures = sum(1 for _ in me.empty_structures()) + my_animals\n\n    # --- Hiring ---------------------------------------------------------\n    schedule = HIRE_SCHEDULE[day] if day < len(HIRE_SCHEDULE) else 8\n    # Rough workload: tiles needing daily touches + animal chores.\n    workload = sum(crops.values()) + 2 * my_animals + 10\n    cap_by_work = max(3, workload // 3)\n    plan.hires_target = min(schedule, cap_by_work)\n    budget = max(150.0, me.money * 0.25)  # hands are cheap; never starve labor\n    while plan.hires_target > 2 and econ.hire_total_cost(plan.hires_target) > budget:\n        plan.hires_target -= 1\n\n    # --- Land -------------------------------------------------------------\n    # (May be extended below once quotas/builds are known: land_pressure.)\n    plan.land_buys = []\n    owned = me.unlocked_quadrants\n    next_idx = sum(1 for q in LAND_ORDER if q in owned)\n    if next_idx < len(LAND_ORDER) and day <= 22:\n        price = LAND_PRICES[next_idx]\n        # Buy only when the current land is actually filling up.\n        empty = sum(1 for _ in me.empty_tiles())\n        if me.money >= price + 600 and empty < 12:\n            plan.land_buys.append(LAND_ORDER[next_idx])\n\n    # --- Planting quotas (tiles to add today per crop) --------------------\n    quota = {}\n    if not plan.liquidation:\n        # Melon: adaptive to the shared market depth and opponent supply.\n        if day <= MELON_LAST_PLANT_DAY:\n            opp_supply = _projected_melons(view.opp)\n            my_supply = (\n                _projected_melons(me)\n                + view.shed.get("MELON", 0)\n                + memory.melons_sold\n            )\n            room = MELON_SUPPLY_TARGET - opp_supply - my_supply\n            if room > 0:\n                quota["MELON"] = min(10, max(0, room // CROPS["MELON"]["max_yield"]))\n\n        # Wheat: rolling engine sized to labor, feed needs, and land.\n        wheat_target = min(WHEAT_TILE_CAP, 8 + my_animals)\n        if day <= WHEAT_LAST_PLANT_DAY:\n            quota["WHEAT"] = max(0, wheat_target - crops.get("WHEAT", 0))\n\n        # Carrot: scale with town demand (PET_CAFE 2x, FARMERS_MARKET 1x).\n        pet = view.unlocked_shops.count("PET_CAFE")\n        fm = view.unlocked_shops.count("FARMERS_MARKET")\n        carrot_target = min(CARROT_TILE_CAP, 6 + 3 * pet + 2 * fm)\n        if day <= CARROT_LAST_PLANT_DAY:\n            quota["CARROT"] = max(0, carrot_target - crops.get("CARROT", 0))\n\n        # Tomato: scale with pizza shops / farmers markets.\n        pizza = view.unlocked_shops.count("PIZZA_SHOP")\n        tomato_target = min(TOMATO_TILE_CAP, 6 + 3 * pizza + 2 * fm)\n        if day <= TOMATO_LAST_PLANT_DAY:\n            quota["TOMATO"] = max(0, tomato_target - crops.get("TOMATO", 0))\n\n        # Strawberry: a trap at base demand, but 2+ consuming shops push its\n        # drain far past T=100 and the price holds $200+ all season.\n        straw_shops = sum(\n            view.unlocked_shops.count(s)\n            for s in ("BRUNCH_SPOT", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP", "FARMERS_MARKET")\n        )\n        if straw_shops >= 2 and day <= 13:  # 4 productions need planting by ~13\n            straw_target = min(10, 3 * straw_shops)\n            quota["STRAWBERRY"] = max(0, straw_target - crops.get("STRAWBERRY", 0))\n    plan.plant_quota = quota\n\n    # --- Animals (adaptive to town demand) ----------------------------------\n    plan.animal_buys = {}\n    plan.structure_builds = {"COOP": 0, "PASTURE": 0}\n    herd = {}\n    for _, _, t in me.animals():\n        herd[t["animal"]] = herd.get(t["animal"], 0) + 1\n    empty_by_kind = {"COOP": 0, "PASTURE": 0}\n    for _, _, t in me.empty_structures():\n        empty_by_kind[t["kind"]] = empty_by_kind.get(t["kind"], 0) + 1\n\n    # Milk/wool are traps at base demand, but town shops can push their drain\n    # far past T: then they hold near/above base price all season.\n    milk_shops = sum(\n        view.unlocked_shops.count(s) for s in ("PIZZA_SHOP", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP")\n    )\n    yarn_shops = view.unlocked_shops.count("YARN_STORE")\n    targets = {\n        "GOOSE": GEESE_TARGET if day <= GEESE_LAST_BUY_DAY else 0,\n        "COW": min(8, 4 * milk_shops) if day <= 18 else 0,\n        "SHEEP": min(10, 4 * yarn_shops) if day <= 20 else 0,\n    }\n\n    if not plan.liquidation and day >= GEESE_BUY_START_DAY:\n        # Feed security: never grow the herd past what the wheat pipeline\n        # (stock + growing tiles + market top-ups) can keep alive.\n        feed_capacity = view.shed.get("WHEAT", 0) + 3 * crops.get("WHEAT", 0) + 10\n        budget = max(0.0, me.money - 400)\n        feedable = max(0, feed_capacity - my_animals)\n        per_day_left = GEESE_PER_DAY\n        for kind in ("COW", "SHEEP", "GOOSE"):  # scarce-demand animals first\n            cost = ANIMALS[kind]["cost"]\n            want = targets[kind] - herd.get(kind, 0) - view.shed.get(kind, 0)\n            n = max(0, min(want, int(budget // cost), feedable, per_day_left))\n            if n > 0:\n                plan.animal_buys[kind] = n\n                budget -= n * cost\n                feedable -= n\n                per_day_left -= n\n\n    # Structures (free to build): cover the delivery pipeline per kind.\n    for kind, structure in (("GOOSE", "COOP"), ("COW", "PASTURE"), ("SHEEP", "PASTURE")):\n        pipeline = plan.animal_buys.get(kind, 0) + view.shed.get(kind, 0)\n        need = pipeline - empty_by_kind.get(structure, 0)\n        if need > 0:\n            plan.structure_builds[structure] += need\n            empty_by_kind[structure] = 0\n        else:\n            empty_by_kind[structure] = -need\n\n    # --- Feed reserve -------------------------------------------------------\n    plan.wheat_reserve = 0 if plan.liquidation and day >= 29 else my_animals + 2\n\n    # --- Sell floors ---------------------------------------------------------\n    plan.sell_floors = _sell_floors(view)\n    return plan\n\n\ndef apply_land_pressure(plan, view):\n    """Demand-driven land expansion safety net for the NEURAL plan path only:\n    the land head overwrites the heuristic\'s land logic, so without this a\n    learned policy can strand itself on 25 tiles while a shop wave makes\n    pastures profitable. The scripted heuristic keeps its own tuned rule —\n    adding this trigger there regressed it 10-17 vs v3 (cash starved the\n    melon rush)."""\n    if plan.land_buys or plan.liquidation or not (2 <= view.day <= 24):\n        return\n    owned = view.me.unlocked_quadrants\n    next_idx = sum(1 for q in LAND_ORDER if q in owned)\n    if next_idx >= len(LAND_ORDER):\n        return\n    # Only count work that could actually land today (labor caps).\n    pending = min(sum(plan.plant_quota.values()), 12) + sum(plan.structure_builds.values())\n    empty = sum(1 for _ in view.me.empty_tiles())\n    price = LAND_PRICES[next_idx]\n    if empty < pending + 2 and view.me.money >= price + 1500:\n        plan.land_buys.append(LAND_ORDER[next_idx])\n\n\ndef _sell_floors(view):\n    """Minimum acceptable marginal sell price per item. Flat during the\n    season (cash compounds), sliding to $1 over the final days so nothing is\n    left unsold."""\n    step = view.step\n    decay_start = FLOOR_DECAY_DAY * TURNS_PER_DAY\n\n    def decayed(base_floor):\n        if step < decay_start:\n            return base_floor\n        if step >= FINAL_STEP - 4:\n            return 1\n        frac = (FINAL_STEP - step) / (FINAL_STEP - decay_start)\n        return max(1, int(base_floor * frac))\n\n    # Fertilizer has ZERO town demand: its price falls monotonically as both\n    # players dump animal fertilizer, and never recovers. Earliest sale is\n    # always the best sale — and a fertilizer hoard blocks the shed, whose\n    # midnight overflow silently destroys produce.\n    # (floor stays 1; see return dict below)\n\n    # Opponent melons about to ripen -> dump ours before the crash.\n    melon_floor = MELON_FLOOR\n    opp_ripening = sum(\n        1\n        for _, _, t in view.opp.plants()\n        if t["crop"] == "MELON" and view.day - t["planted_day"] >= 8\n    )\n    if opp_ripening >= 3:\n        melon_floor = 40\n\n    # Milk/wool floors rise with town demand: heavy shop drain keeps their\n    # scarce-side prices propped up, so only sell into strength.\n    milk_shops = sum(\n        view.unlocked_shops.count(s) for s in ("PIZZA_SHOP", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP")\n    )\n    yarn_shops = view.unlocked_shops.count("YARN_STORE")\n\n    straw_shops = sum(\n        view.unlocked_shops.count(s)\n        for s in ("BRUNCH_SPOT", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP", "FARMERS_MARKET")\n    )\n    return {\n        "WHEAT": 1,\n        "EGG": 1,\n        "MELON": decayed(melon_floor),\n        "FERTILIZER": 1,\n        "CARROT": decayed(CARROT_FLOOR),\n        "TOMATO": decayed(TOMATO_FLOOR),\n        "STRAWBERRY": decayed(180 if straw_shops >= 3 else 80),\n        "MILK": decayed(130 if milk_shops >= 1 else 100),\n        "WOOL": decayed(160 if yarn_shops >= 1 else 120),\n    }\n'),
    ('scheduler', '"""Turn-level task generation and greedy unit assignment.\n\nRecomputed from scratch every turn (no cross-turn path state): the midnight\nrespawn of all units at the shed needs no special-casing.\n"""\n\n\n# Task priorities (lower = more urgent).\nP_SURVIVAL = 0\nP_HARVEST = 1\nP_TEND = 2\nP_GROW = 3\nP_FILLER = 5\n\nPLANT_LAST_HOUR = 21  # leave >= 2 turns to water the fresh plant\nDROP_THRESHOLD = 10   # mid-game inventory size that triggers a shed trip\n\n\nclass Task:\n    __slots__ = ("pri", "x", "y", "op", "need")\n\n    def __init__(self, pri, x, y, op, need=None):\n        self.pri = pri\n        self.x = x\n        self.y = y\n        self.op = op\n        self.need = need  # item that must be in the unit\'s inventory\n\n\ndef _dist(x1, y1, x2, y2):\n    return abs(x1 - x2) + abs(y1 - y2)\n\n\ndef _step_toward(fx, fy, tx, ty):\n    dx, dy = tx - fx, ty - fy\n    if abs(dx) >= abs(dy) and dx != 0:\n        return "EAST" if dx > 0 else "WEST"\n    if dy != 0:\n        return "SOUTH" if dy > 0 else "NORTH"\n    if dx != 0:\n        return "EAST" if dx > 0 else "WEST"\n    return None\n\n\ndef _nearest_shed_tile(x, y):\n    return min(SHED_ACCESS, key=lambda t: _dist(x, y, t[0], t[1]))\n\n\ndef _unlocked(view, x, y):\n    return view.me.tile(x, y) != "LOCKED"\n\n\ndef build_tasks(view, plan):\n    """Generate this turn\'s pending tile tasks."""\n    tasks = []\n    day = view.day\n    me = view.me\n\n    fert_targets = set()\n\n    # --- Plants: water / harvest / fertilize ---------------------------------\n    for x, y, t in me.plants():\n        crop = CROPS.get(t["crop"])\n        if crop is None:\n            continue\n        age = day - t["planted_day"]\n        yields = t.get("yield_units", 0)\n\n        # Harvest.\n        decaying = 0 <= t.get("max_lifespan_step", -1) <= view.step + 24\n        if crop["ongoing"]:\n            if yields >= crop["max_yield"] - 1 or (yields > 0 and (decaying or plan.liquidation)):\n                tasks.append(Task(P_HARVEST, x, y, ["HARVEST"]))\n        else:\n            ripe = age >= crop["first_yield_day"] and (\n                yields >= crop["max_yield"] or age >= crop["max_yield_day"]\n            )\n            if ripe or (yields > 0 and decaying and age >= crop["first_yield_day"]):\n                tasks.append(Task(P_HARVEST if not decaying else P_SURVIVAL, x, y, ["HARVEST"]))\n                continue  # will be gone; no watering needed\n\n        # Fertilize (before watering the same tile): tomato production days\n        # and the start of wheat/carrot bonus windows.\n        if t.get("fertilized_until_day", -1) < day and not plan.liquidation:\n            want_fert = (\n                (t["crop"] == "TOMATO" and age in (8, 11))\n                or (t["crop"] == "WHEAT" and age == 2)\n                or (t["crop"] == "CARROT" and age == 2)\n            )\n            if want_fert:\n                tasks.append(Task(P_TEND, x, y, ["FERTILIZE"], need="FERTILIZER"))\n                fert_targets.add((x, y))\n\n    for x, y, t in me.plants():\n        if t.get("watered_today"):\n            continue\n        crop = CROPS.get(t["crop"])\n        if crop is None:\n            continue\n        age = day - t["planted_day"]\n        # Suppress the bonus water until the fertilizer lands (early in the day).\n        if (x, y) in fert_targets and t.get("consecutive_unwatered", 0) == 0 and view.hour < 18:\n            continue\n        if t.get("consecutive_unwatered", 0) >= 1:\n            pri = P_SURVIVAL  # dies tonight if unwatered\n        elif not crop["ongoing"] and (crop["max_yield_day"] + 1) // 2 <= age <= crop["max_yield_day"]:\n            pri = P_TEND      # bonus-window water\n        elif crop["ongoing"]:\n            pri = P_TEND if t.get("fertilized_until_day", -1) >= day else P_FILLER\n        else:\n            pri = P_FILLER    # keeps consecutive_unwatered at 0; cheap insurance\n        tasks.append(Task(pri, x, y, ["WATER"]))\n\n    # --- Animals ---------------------------------------------------------------\n    # Day 29 has no end-of-day refresh: feeding then is pure waste.\n    feeding_day = day < 29\n    for x, y, t in me.animals():\n        ruminant = t.get("animal") in ("COW", "SHEEP")\n        if feeding_day and not t.get("fed_today"):\n            # cu >= 1 means the animal escapes tonight if unfed: hard deadline.\n            # Cows/sheep are fed daily so CARE can bank (+1 product each\n            # fed+cared day, paid on the next production: ~$125+/action).\n            if t.get("consecutive_unfed", 0) >= 1:\n                pri = P_SURVIVAL\n            else:\n                pri = P_TEND if ruminant else P_FILLER\n            tasks.append(Task(pri, x, y, ["FEED"], need="WHEAT"))\n        if feeding_day and t.get("fed_today") and not t.get("cared_today") and day < 28:\n            tasks.append(Task(P_TEND if ruminant else P_FILLER, x, y, ["CARE"]))\n        if t.get("fertilizer_available"):\n            tasks.append(Task(P_TEND, x, y, ["COLLECT_FERTILIZER"]))\n        held = t.get("yield_units", 0)\n        max_held = ANIMALS.get(t.get("animal"), {}).get("max_held", 4)\n        if held >= max_held - 1 or (held > 0 and plan.liquidation):\n            tasks.append(Task(P_HARVEST, x, y, ["HARVEST"]))\n\n    # --- Growth: builds, goose placement, planting ------------------------------\n    empties = sorted(\n        me.empty_tiles(), key=lambda p: _dist(p[0], p[1], 4, 4) + _dist(p[0], p[1], 5, 5)\n    )\n    cursor = 0\n    for structure, op in (("COOP", "BUILD_COOP"), ("PASTURE", "BUILD_PASTURE")):\n        for _ in range(plan.structure_builds.get(structure, 0)):\n            if cursor >= len(empties):\n                break\n            x, y = empties[cursor]\n            cursor += 1\n            tasks.append(Task(P_GROW, x, y, [op]))\n\n    available = {}\n    for kind in ("GOOSE", "COW", "SHEEP"):\n        available[kind] = view.shed.get(kind, 0) + sum(\n            view.unit_inv(i).get(kind, 0) for i, _, _ in me.units\n        )\n    for x, y, t in me.empty_structures():\n        kinds = ("GOOSE",) if t["kind"] == "COOP" else ("COW", "SHEEP")\n        for kind in kinds:\n            if available.get(kind, 0) > 0:\n                available[kind] -= 1\n                tasks.append(Task(P_TEND, x, y, ["PLACE", kind], need=kind))\n                break\n\n    if view.hour <= PLANT_LAST_HOUR:\n        for crop, n in plan.plant_quota.items():\n            for _ in range(n):\n                if cursor >= len(empties):\n                    break\n                x, y = empties[cursor]\n                cursor += 1\n                tasks.append(Task(P_GROW, x, y, ["PLANT", crop]))\n\n    # --- Weeds: keep the farm clear (idle hands are cheap) ------------------------\n    weed_pri = P_GROW if len(empties) - cursor < 6 else P_FILLER\n    for x, y, _ in me.weeds():\n        tasks.append(Task(weed_pri, x, y, ["DIG"]))\n\n    return tasks\n\n\ndef _provision_tasks(view, plan, tasks):\n    """PICKUP tasks that stock units for need-tasks (feed wheat, fertilizer,\n    goose delivery), placed at the shed."""\n    carried = {}\n    for idx, _, _ in view.me.units:\n        for item, n in view.unit_inv(idx).items():\n            carried[item] = carried.get(item, 0) + n\n\n    wants = {}\n    for t in tasks:\n        if t.need:\n            wants[t.need] = wants.get(t.need, 0) + 1\n\n    out = []\n    for item, want in wants.items():\n        shortage = want - carried.get(item, 0)\n        available = max(0, view.shed.get(item, 0))\n        take = min(shortage, available)\n        if take <= 0:\n            continue\n        pri = P_SURVIVAL if item == "WHEAT" else P_TEND\n        # Split large pickups across units: one carrier cannot visit 20 tiles\n        # in a day, and a starved animal escapes.\n        batch = 5 if item == "WHEAT" else 3\n        while take > 0:\n            n = min(batch, take)\n            out.append(Task(pri, -1, -1, ["PICKUP", item, n], need=None))\n            take -= n\n    return out\n\n\ndef _assign_batch(view, plan, ordered, units, free, actions, plant_requests, seeds_left=None):\n    """Greedy nearest-unit assignment of a task batch (mutates free/actions).\n\n    Returns the tasks that could not be assigned this turn (no free/eligible\n    unit, or unreachable) so idle units can pre-position toward them.\n    """\n    seeds_left = seeds_left if seeds_left is not None else {}\n    leftover = []\n    for task in ordered:\n        if not free:\n            leftover.append(task)\n            continue\n\n        if task.op[0] == "PICKUP":\n            idx = min(\n                free,\n                key=lambda i: _dist(\n                    units[i][0], units[i][1], *_nearest_shed_tile(units[i][0], units[i][1])\n                ),\n            )\n            x, y = units[idx]\n            tx, ty = _nearest_shed_tile(x, y)\n            if (x, y) == (tx, ty):\n                actions[idx] = task.op\n            else:\n                step = _step_toward(x, y, tx, ty)\n                actions[idx] = [step] if step else ["PASS"]\n            free.discard(idx)\n            continue\n\n        if task.op[0] == "PLANT":\n            crop = task.op[1]\n            if plant_requests.get(crop, 0) + 1 > seeds_left.get(crop, 0):\n                continue  # atomic-PLANT rule: never over-request\n\n        candidates = [\n            i for i in free if not task.need or view.unit_inv(i).get(task.need, 0) >= 1\n        ]\n        if not candidates:\n            leftover.append(task)\n            continue\n        idx = min(candidates, key=lambda i: _dist(units[i][0], units[i][1], task.x, task.y))\n        x, y = units[idx]\n        if (x, y) == (task.x, task.y):\n            if not _unlocked(view, task.x, task.y):\n                continue\n            actions[idx] = task.op\n            if task.op[0] == "PLANT":\n                plant_requests[task.op[1]] = plant_requests.get(task.op[1], 0) + 1\n        else:\n            d = _dist(x, y, task.x, task.y)\n            if d > view.hours_left_today + 4:\n                leftover.append(task)\n                continue  # unreachable today; idle units can stage toward it\n            step = _step_toward(x, y, task.x, task.y)\n            actions[idx] = [step] if step else ["PASS"]\n        free.discard(idx)\n    return leftover\n\n\ndef assign(view, plan, tasks):\n    """Greedy nearest-unit assignment. Returns {unit_idx: op_list}."""\n    me = view.me\n    units = {idx: (x, y) for idx, x, y in me.units}\n    free = set(units)\n    actions = {}\n    seeds_left = dict(view.seeds)\n    shed_room = max(0, 100 - view.shed_total)\n\n    # Provisioning first (positions resolve to nearest shed tile per unit).\n    pickups = _provision_tasks(view, plan, tasks)\n\n    # Liquidation shuttles: get inventories into the shed so market can sell.\n    drop_tasks = []\n    final_push = view.step >= FINAL_STEP - 10\n    aggressive = view.day >= 29 or final_push\n    for idx, x, y in me.units:\n        inv = view.unit_inv(idx)\n        # Working stock is not cargo: geese are being delivered to coops,\n        # fertilizer is bound for crops, small wheat loads are feed runs.\n        total = sum(\n            n\n            for item, n in inv.items()\n            if not (\n                item in ("GOOSE", "COW", "SHEEP")\n                or (not aggressive and item == "FERTILIZER" and n <= 3)\n                or (not aggressive and item == "WHEAT" and n <= 5)\n            )\n        )\n        if total == 0:\n            continue\n        threshold = 1 if (aggressive and view.hour >= 4) or view.step >= FINAL_STEP - 6 else DROP_THRESHOLD\n        if plan.liquidation and not aggressive:\n            threshold = 8\n        if total >= threshold:\n            drop_tasks.append((idx, total))\n\n    ordered = sorted(pickups + tasks, key=lambda t: (t.pri, t.y, t.x))\n    survival = [t for t in ordered if t.pri == P_SURVIVAL]\n    ordered = [t for t in ordered if t.pri != P_SURVIVAL]\n\n    # Survival tasks (unwatered plants, unfed animals) claim units before\n    # anything else, including liquidation shuttles.\n    leftover = _assign_batch(view, plan, survival, units, free, actions, {}, seeds_left)\n\n    # Forced drops next for units that must shuttle.\n    for idx, total in drop_tasks:\n        if idx not in free:\n            continue\n        x, y = units[idx]\n        tx, ty = _nearest_shed_tile(x, y)\n        if (x, y) == (tx, ty):\n            if shed_room >= total or final_push:\n                actions[idx] = ["DROP"]\n                shed_room = max(0, shed_room - total)\n            else:\n                # Partial drop of the single biggest stack.\n                inv = view.unit_inv(idx)\n                item = max(inv, key=inv.get)\n                n = min(inv[item], shed_room)\n                if n > 0:\n                    actions[idx] = ["PLACE", item, n]\n                    shed_room -= n\n                else:\n                    continue  # no room; let the unit do normal work\n        else:\n            step = _step_toward(x, y, tx, ty)\n            actions[idx] = [step] if step else ["PASS"]\n        free.discard(idx)\n\n    plant_requests = {}\n    leftover += _assign_batch(view, plan, ordered, units, free, actions, plant_requests, seeds_left)\n\n    # Idle units pre-position instead of passing: end-of-day carriers head for\n    # the shed; everyone else stages toward the nearest unassigned task, and\n    # units stranded on locked land walk back to the farm.\n    for idx in list(free):\n        x, y = units[idx]\n        if sum(view.unit_inv(idx).values()) > 0 and view.hour >= TURNS_PER_DAY - 3:\n            tx, ty = _nearest_shed_tile(x, y)\n            step = _step_toward(x, y, tx, ty)\n            actions[idx] = [step] if step else (["DROP"] if shed_room > 0 else ["PASS"])\n            free.discard(idx)\n            continue\n        target = None\n        best = 10**9\n        # Hands vanish at midnight and the farmer teleports home, so staging\n        # toward future work only pays while there is day left to use it.\n        if view.hours_left_today > 6:\n            for t in leftover:\n                # Only stage toward tasks this unit could actually perform on\n                # arrival; a need-task (feed/fertilize/place) without the item\n                # in hand would strand the unit next to work it can\'t do.\n                if t.x < 0 or (t.need and view.unit_inv(idx).get(t.need, 0) < 1):\n                    continue\n                d = _dist(x, y, t.x, t.y)\n                if d < best:\n                    best, target = d, t\n        if target is not None:\n            step = _step_toward(x, y, target.x, target.y)\n            actions[idx] = [step] if step else ["PASS"]\n        elif not _unlocked(view, x, y):\n            step = _step_toward(x, y, 4, 4)\n            actions[idx] = [step] if step else ["PASS"]\n        else:\n            actions[idx] = ["PASS"]\n        free.discard(idx)\n\n    return actions\n'),
    ('market', '"""Market controller: builds the (priority-ordered, <=10) market order list."""\n\n\n\ndef build_orders(view, plan, memory):\n    orders = []\n    money = view.me.money\n    final_push = view.step >= FINAL_STEP - 8\n\n    def add(order):\n        if len(orders) < MAX_MARKET_ORDERS:\n            orders.append(order)\n            return True\n        return False  # cap reached; the engine would silently drop it\n\n    # --- Liquidation endgame: selling takes absolute priority ---------------\n    if final_push:\n        for sell in _sell_orders(view, plan, memory):\n            if add(sell) and sell[1] == "MELON":\n                memory.melons_sold += sell[2]\n        return orders\n\n    # --- HIRE (first hours of the day only) ---------------------------------\n    if view.hour <= 1:\n        need = plan.hires_target - view.me.hires_today\n        cost_guard = 0\n        hired = 0\n        while need > 0 and hired < 8:\n            cost_guard += econ.hire_marginal_cost(view.me.hires_today + hired)\n            if cost_guard > money * 0.3 or not add(["HIRE"]):\n                break\n            hired += 1\n            need -= 1\n\n    # --- Feed buffer: keep a full day of wheat for every animal -------------\n    animals = sum(1 for _ in view.me.animals())\n    if animals and view.day < 29:\n        wheat_stock = view.shed.get("WHEAT", 0) + sum(\n            view.unit_inv(i).get("WHEAT", 0) for i, _, _ in view.me.units\n        )\n        deficit = animals - wheat_stock\n        hungry_now = sum(\n            1\n            for _, _, t in view.me.animals()\n            if not t.get("fed_today") and t.get("consecutive_unfed", 0) >= 1\n        )\n        # Don\'t chase a self-inflicted wheat price spiral for buffer stock;\n        # survival feeds are bought at any price.\n        pricey = view.market_prices.get("WHEAT", 25) > 40\n        if deficit > 0 and money > 100 and (hungry_now > wheat_stock or not pricey):\n            add(["BUY_PRODUCT", "WHEAT", min(deficit, 15)])\n\n    # --- Land ----------------------------------------------------------------\n    remaining_land = []\n    for quad in plan.land_buys:\n        if not add(["BUY_LAND"]):\n            remaining_land.append(quad)\n    plan.land_buys = remaining_land\n\n    # --- Animals (before seeds: a dropped seed order self-heals next turn) ----\n    for kind in list(plan.animal_buys):\n        want = plan.animal_buys[kind]\n        cost = ANIMALS[kind]["cost"]\n        n = min(want, int(money // cost))\n        if n > 0 and add(["BUY_ANIMAL", kind, n]):\n            plan.animal_buys[kind] = want - n\n            money -= n * cost\n\n    # --- Seeds: cover the remaining quota (bought this turn, plantable next) --\n    last_plant_day = {"MELON": 19, "WHEAT": 25, "CARROT": 26, "TOMATO": 18, "STRAWBERRY": 13}\n    for crop, remaining in plan.plant_quota.items():\n        if view.day > last_plant_day.get(crop, 29) or view.hour > 20:\n            continue  # planting window closing; don\'t strand seeds\n        deficit = remaining - view.seeds.get(crop, 0)\n        if deficit > 0 and money >= CROPS[crop]["seed"]:\n            affordable = int(money * 0.6 // CROPS[crop]["seed"])\n            n = min(deficit, max(1, affordable))\n            if n > 0:\n                add(["BUY_SEED", crop, n])\n\n    # --- Sells fill the remaining slots ---------------------------------------\n    for sell in _sell_orders(view, plan, memory):\n        if not add(sell):\n            break\n        if sell[1] == "MELON":\n            memory.melons_sold += sell[2]\n\n    return orders\n\n\ndef _sell_orders(view, plan, memory):\n    """One SELL order per item, sized to the marginal-revenue floor."""\n    floors = plan.sell_floors\n    # Shed pressure valve: midnight overflow is silently destroyed, so when\n    # the shed runs hot, dump the biggest stacks at any price.\n    pressure = view.shed_total > 80\n    candidates = []\n    for item, stock in view.shed.items():\n        if stock <= 0 or item in ANIMALS:\n            continue\n        if item == "WHEAT":\n            stock = max(0, stock - plan.wheat_reserve)\n        if stock <= 0:\n            continue\n        floor = 1 if (pressure and stock >= 10) else floors.get(item, 1)\n        inv = view.market_inv.get(item)\n        if inv is None:\n            continue\n        n = econ.units_sellable_above(item, inv, floor, cap=stock)\n        if n <= 0:\n            continue\n        revenue = econ.sell_revenue(item, inv, n)\n        candidates.append((revenue, item, n))\n\n    candidates.sort(reverse=True)\n    return [["SELL", item, n] for _, item, n in candidates]\n'),
    ('features', '"""Shared observation encoding and action-head spec for the neural planner.\n\nUsed identically at training time (rl/) and inference time (nnpolicy.py) so\ntrain/serve skew is impossible. Pure stdlib.\n\nThe RL agent acts once per day: a masked multi-discrete decision that fills\nthe strategic fields of DayPlan; the scripted scheduler/market executors\nhandle the per-turn micro. Masks make rule-violating or infeasible choices\nunsamplable (Huang & Ontanon: mask before softmax keeps the gradient\nunbiased).\n"""\n\nimport math\n\n\n# ---- Action heads -----------------------------------------------------------\n# name -> list of choice values. The network emits one categorical per head.\n# Crop/animal heads are ABSOLUTE standing targets (tiles on the farm, animals\n# in the herd), not per-day deltas: targets are stable across days, so the BC\n# distribution isn\'t drowned in zeros and argmax play is coherent. The daily\n# delta (plant quota / buys) is derived in apply_to_plan.\nHEADS = [\n    ("melon_tiles", [0, 6, 12, 18, 24]),\n    ("wheat_tiles", [0, 6, 12, 18, 24]),\n    ("carrot_tiles", [0, 4, 8, 12, 16]),\n    ("tomato_tiles", [0, 4, 8, 12]),\n    ("straw_tiles", [0, 4, 8, 12]),\n    ("goose_target", [0, 8, 16, 24, 32]),\n    ("cow_target", [0, 2, 4, 8]),\n    ("sheep_target", [0, 3, 6, 10]),\n    ("hires", [4, 8, 12, 14, 16]),\n    ("land", [0, 1]),\n    ("melon_floor", [1, 40, 80, 120, 180]),\n    # Multipliers on the heuristic\'s adaptive sell floors: hold out for\n    # scarcity spikes (>1) or liquidate into current demand (<1).\n    ("premium_floor_scale", [0.6, 1.0, 1.4]),   # STRAWBERRY / MILK / WOOL\n    ("staple_floor_scale", [0.7, 1.0, 1.3]),    # CARROT / TOMATO\n]\nHEAD_SIZES = [len(vals) for _, vals in HEADS]\nN_ACTION_LOGITS = sum(HEAD_SIZES)\n\nQUOTA_CROP = {\n    "melon_tiles": "MELON",\n    "wheat_tiles": "WHEAT",\n    "carrot_tiles": "CARROT",\n    "tomato_tiles": "TOMATO",\n    "straw_tiles": "STRAWBERRY",\n}\nBUY_KIND = {"goose_target": "GOOSE", "cow_target": "COW", "sheep_target": "SHEEP"}\n\nPLANTS_PER_DAY_CAP = 12   # labor limit on new plantings per day\nBUYS_PER_DAY_CAP = 10\n\n# Last day each crop is still worth planting (harvest must land by day 29).\nLAST_PLANT = {"MELON": 19, "WHEAT": 25, "CARROT": 26, "TOMATO": 18, "STRAWBERRY": 13}\n\nSHOP_NAMES = sorted(SHOPS)\n\n\ndef supply_projection(farm, day, horizon=7):\n    """Rough units of each product this farm brings to market over the next\n    `horizon` days from standing crops and animals (public info for both)."""\n    horizon = max(0, min(horizon, 29 - day))\n    supply = {p: 0.0 for p in PRODUCTS}\n    for _, _, t in farm.plants():\n        crop = CROPS.get(t.get("crop"))\n        if not crop:\n            continue\n        age = day - t.get("planted_day", day)\n        yld = t.get("yield_units", 0)\n        if crop["ongoing"]:\n            per_day = 1.0 / (crop["interval"] + 1)\n            supply[t["crop"]] += min(crop["max_yield"] * 2, yld + per_day * horizon)\n        else:\n            window_start = (crop["max_yield_day"] + 1) // 2\n            bonus_left = max(\n                0, min(crop["max_yield_day"], age + horizon) - max(age, window_start)\n            )\n            supply[t["crop"]] += min(crop["max_yield"], yld + bonus_left + 1)\n    for _, _, t in farm.animals():\n        a = ANIMALS.get(t.get("animal"))\n        if not a:\n            continue\n        supply[a["product"]] += t.get("yield_units", 0) + horizon / a["interval"]\n        supply["FERTILIZER"] += horizon\n    return supply\n\n\ndef _crop_stats(farm, day):\n    stats = {}\n    for crop in CROPS:\n        stats[crop] = [0, 0.0, 0]  # count, mean age, harvestable yield\n    for _, _, t in farm.plants():\n        crop = t.get("crop")\n        if crop not in stats:\n            continue\n        s = stats[crop]\n        s[0] += 1\n        s[1] += day - t.get("planted_day", day)\n        s[2] += t.get("yield_units", 0)\n    return stats\n\n\ndef encode(view, memory):\n    """View (+Memory) -> flat feature list."""\n    f = []\n    day = view.day\n    me, opp = view.me, view.opp\n\n    # Time\n    f.append(day / 30.0)\n    f.append(view.hour / 24.0)\n    f.append(view.steps_left / 718.0)\n\n    # My economy\n    f.append(math.log1p(max(0.0, me.money)) / 10.0)\n    f.append(len(me.units) / 16.0)\n    f.append(me.hires_today / 16.0)\n    f.append(len(me.unlocked_quadrants) / 4.0)\n\n    my_crops = _crop_stats(me, day)\n    for crop in CROPS:\n        c, age_sum, yld = my_crops[crop]\n        f.append(c / 12.0)\n        f.append((age_sum / c if c else 0.0) / 12.0)\n        f.append(yld / 30.0)\n\n    herd = {k: 0 for k in ANIMALS}\n    empty_structs = {"COOP": 0, "PASTURE": 0}\n    pending_yield = 0\n    for _, _, t in me.animals():\n        herd[t["animal"]] = herd.get(t["animal"], 0) + 1\n        pending_yield += t.get("yield_units", 0)\n    for _, _, t in me.empty_structures():\n        empty_structs[t["kind"]] = empty_structs.get(t["kind"], 0) + 1\n    for k in ANIMALS:\n        f.append(herd[k] / 16.0)\n    f.append(empty_structs["COOP"] / 10.0)\n    f.append(empty_structs["PASTURE"] / 10.0)\n    f.append(pending_yield / 60.0)\n    f.append(sum(1 for _ in me.empty_tiles()) / 60.0)\n    f.append(sum(1 for _ in me.weeds()) / 20.0)\n\n    # Shed / seeds\n    for item in PRODUCTS:\n        f.append(view.shed.get(item, 0) / 30.0)\n    for crop in CROPS:\n        f.append(view.seeds.get(crop, 0) / 10.0)\n    f.append(view.shed_total / 100.0)\n\n    # Market: normalized inventory displacement and price ratio per product\n    for item in PRODUCTS:\n        p = MARKET_PARAMS[item]\n        inv = view.market_inv.get(item, p["I0"])\n        f.append(max(-3.0, min(3.0, (inv - p["I0"]) / p["T"])) / 3.0)\n        f.append(view.market_prices.get(item, p["base"]) / (2.0 * p["base"]))\n\n    # Town demand\n    for shop in SHOP_NAMES:\n        f.append(view.unlocked_shops.count(shop) / 3.0)\n\n    # Opponent (public)\n    f.append(math.log1p(max(0.0, opp.money)) / 10.0)\n    f.append(len(opp.units) / 16.0)\n    f.append(len(opp.unlocked_quadrants) / 4.0)\n    opp_crops = _crop_stats(opp, day)\n    for crop in CROPS:\n        c, _, yld = opp_crops[crop]\n        f.append(c / 12.0)\n        f.append(yld / 30.0)\n    f.append(sum(1 for _ in opp.animals()) / 16.0)\n\n    # Demand vs supply: my and opponent\'s projected 7-day output per product,\n    # town drain per day, the resulting gap, and price curvature (what the\n    # 12th marginal unit would fetch). This is the "harvest over the field\n    # relative to demand" signal.\n    my_supply = supply_projection(me, day)\n    opp_supply = supply_projection(opp, day)\n    drain = econ.town_drain_per_day(view.unlocked_shops)\n    horizon = max(0.0, min(7.0, 29 - day))\n    for item in PRODUCTS:\n        p = MARKET_PARAMS[item]\n        f.append(my_supply[item] / 40.0)\n        f.append(opp_supply[item] / 40.0)\n        f.append(drain.get(item, 0.0) / 12.0)\n        gap = drain.get(item, 0.0) * horizon - my_supply[item] - opp_supply[item]\n        f.append(max(-2.0, min(2.0, gap / 40.0)))\n        inv = view.market_inv.get(item, p["I0"])\n        f.append(econ.price(item, inv + 12) / (2.0 * p["base"]))\n\n    # Land expansion economics.\n    next_idx = sum(1 for q in LAND_ORDER if q in me.unlocked_quadrants)\n    if next_idx < len(LAND_ORDER):\n        price = LAND_PRICES[next_idx]\n        f.append(price / 4000.0)\n        f.append(max(-1.0, min(1.0, (me.money - price) / 2000.0)))\n    else:\n        f.append(0.0)\n        f.append(0.0)\n\n    # Episode memory\n    f.append(getattr(memory, "melons_sold", 0) / 150.0)\n\n    return f\n\n\nN_FEATURES = None  # resolved lazily on first encode (kept in sync by tests)\n\n\ndef masks(view):\n    """Per-head validity masks (list of lists of 0/1), same order as HEADS.\n\n    Targets are self-clamping in apply_to_plan (a target below the current\n    count is simply a no-op), so most heads stay fully valid; only choices\n    that are strictly impossible are masked.\n    """\n    me = view.me\n    money = me.money\n    out = []\n    for name, vals in HEADS:\n        if name == "land":\n            owned = me.unlocked_quadrants\n            next_idx = sum(1 for q in LAND_ORDER if q in owned)\n            can = next_idx < len(LAND_ORDER) and money >= LAND_PRICES[next_idx] + 400\n            m = [1 if (v == 0 or can) else 0 for v in vals]\n        else:\n            m = [1] * len(vals)\n        if not any(m):\n            m[0] = 1\n        out.append(m)\n    return out\n\n\ndef apply_to_plan(plan, choices, view):\n    """Overwrite the strategic fields of a heuristic DayPlan with the network\'s\n    per-head choices (indices into HEADS values). Safety clamps stay scripted:\n    feed capacity, structure pipelines, wheat reserve, and liquidation are\n    computed downstream exactly as in the heuristic planner."""\n    values = {name: vals[choices[i]] for i, (name, vals) in enumerate(HEADS)}\n\n    crop_counts = {}\n    for _, _, t in view.me.plants():\n        crop_counts[t["crop"]] = crop_counts.get(t["crop"], 0) + 1\n\n    quota = {}\n    budget_day = PLANTS_PER_DAY_CAP\n    for head, crop in QUOTA_CROP.items():\n        target = values[head]\n        deficit = max(0, target - crop_counts.get(crop, 0))\n        n = min(deficit, budget_day)\n        if n > 0 and view.day <= LAST_PLANT[crop] and not plan.liquidation:\n            quota[crop] = n\n            budget_day -= n\n    plan.plant_quota = quota\n\n    herd = {}\n    for _, _, t in view.me.animals():\n        herd[t["animal"]] = herd.get(t["animal"], 0) + 1\n\n    plan.animal_buys = {}\n    feed_capacity = view.shed.get("WHEAT", 0) + 3 * crop_counts.get("WHEAT", 0) + 10\n    herd_total = sum(herd.values())\n    feedable = max(0, feed_capacity - herd_total)\n    budget = max(0.0, view.me.money - 300)\n    buys_day = BUYS_PER_DAY_CAP\n    for head, kind in BUY_KIND.items():\n        target = values[head]\n        deficit = max(0, target - herd.get(kind, 0) - view.shed.get(kind, 0))\n        n = max(0, min(deficit, feedable, buys_day, int(budget // ANIMALS[kind]["cost"])))\n        if n > 0 and not plan.liquidation and view.day <= 24:\n            plan.animal_buys[kind] = n\n            feedable -= n\n            buys_day -= n\n            budget -= n * ANIMALS[kind]["cost"]\n\n    # Structure pipeline per kind (same logic as heuristic planner).\n    empty_by_kind = {"COOP": 0, "PASTURE": 0}\n    for _, _, t in view.me.empty_structures():\n        empty_by_kind[t["kind"]] = empty_by_kind.get(t["kind"], 0) + 1\n    plan.structure_builds = {"COOP": 0, "PASTURE": 0}\n    for kind, structure in (("GOOSE", "COOP"), ("COW", "PASTURE"), ("SHEEP", "PASTURE")):\n        pipeline = plan.animal_buys.get(kind, 0) + view.shed.get(kind, 0)\n        need = pipeline - empty_by_kind.get(structure, 0)\n        if need > 0:\n            plan.structure_builds[structure] += need\n            empty_by_kind[structure] = 0\n        else:\n            empty_by_kind[structure] = -need\n\n    plan.hires_target = values["hires"]\n\n    plan.land_buys = []\n    owned = view.me.unlocked_quadrants\n    next_idx = sum(1 for q in LAND_ORDER if q in owned)\n    if next_idx < len(LAND_ORDER):\n        # Learned head, backed by the heuristic\'s tuned land-crunch fallback\n        # so the policy can never simply refuse to expand while tiles run out.\n        empty = sum(1 for _ in view.me.empty_tiles())\n        crunch = (\n            view.day <= 22\n            and empty < 12\n            and view.me.money >= LAND_PRICES[next_idx] + 600\n        )\n        if values["land"] == 1 or crunch:\n            plan.land_buys.append(LAND_ORDER[next_idx])\n\n    plan.sell_floors = dict(plan.sell_floors)\n    plan.sell_floors["MELON"] = (\n        1 if view.step >= 714 else values["melon_floor"]\n    )\n    # Learned scaling of the adaptive heuristic floors (never below $1, and\n    # forced to $1 in the final liquidation push).\n    if view.step < 714:\n        for item in ("STRAWBERRY", "MILK", "WOOL"):\n            plan.sell_floors[item] = max(1, int(plan.sell_floors[item] * values["premium_floor_scale"]))\n        for item in ("CARROT", "TOMATO"):\n            plan.sell_floors[item] = max(1, int(plan.sell_floors[item] * values["staple_floor_scale"]))\n\n    # Scripted safety net: expand land when planned work exceeds open tiles.\n    apply_land_pressure(plan, view)\n    return plan\n'),
    ('nnpolicy', '"""Neural day-planner: a tiny masked multi-discrete MLP in pure stdlib.\n\nThe network only replaces the STRATEGIC fields of DayPlan (quotas, animal\nbuys, hires, land, melon floor) once per day; the proven scripted scheduler\nand market controller execute the micro. ~25k multiply-adds per day-decision,\nso inference cost is irrelevant next to the 1s/step budget.\n\nWeights ship as base85-encoded float32 in kagent/weights.py (generated by\nrl/export.py; None by default -> HeuristicPolicy is used instead).\n"""\n\nimport base64\nimport math\nimport struct\n\n\n\ndef decode_weights(data):\n    """{"sizes": [...], "b85": str} -> list of per-layer [W (rows list), b]."""\n    if not data:\n        return None\n    raw = base64.b85decode(data["b85"].encode("ascii"))\n    flat = list(struct.unpack("<%df" % (len(raw) // 4), raw))\n    sizes = data["sizes"]  # [(in, out), ...]\n    layers = []\n    pos = 0\n    for n_in, n_out in sizes:\n        w = []\n        for _ in range(n_in):\n            w.append(flat[pos : pos + n_out])\n            pos += n_out\n        b = flat[pos : pos + n_out]\n        pos += n_out\n        layers.append((w, b))\n    return layers\n\n\ndef _matvec(w, b, x):\n    out = list(b)\n    for i, xi in enumerate(x):\n        if xi == 0.0:\n            continue\n        row = w[i]\n        for j in range(len(out)):\n            out[j] += xi * row[j]\n    return out\n\n\ndef forward(layers, x):\n    """Returns (action_logits, value). Layers: h1, h2, logits, value."""\n    h = [math.tanh(v) for v in _matvec(layers[0][0], layers[0][1], x)]\n    h = [math.tanh(v) for v in _matvec(layers[1][0], layers[1][1], h)]\n    logits = _matvec(layers[2][0], layers[2][1], h)\n    value = _matvec(layers[3][0], layers[3][1], h)[0]\n    return logits, value\n\n\ndef choose(logits, head_masks, rng=None, temperature=1.0):\n    """Split flat logits by head, mask, and pick (argmax, or sample if rng).\n\n    Returns (choices, logprob_sum). Masked-before-softmax keeps the policy\n    gradient unbiased (Huang & Ontanon 2020).\n    """\n    choices = []\n    logprob = 0.0\n    pos = 0\n    t = temperature if (rng is not None and temperature > 0) else 1.0\n    for (name, vals), mask in zip(features.HEADS, head_masks):\n        n = len(vals)\n        seg = logits[pos : pos + n]\n        pos += n\n        masked = [(seg[i] / t if mask[i] else -1e9) for i in range(n)]\n        mx = max(masked)\n        exps = [math.exp(v - mx) for v in masked]\n        total = sum(exps)\n        probs = [e / total for e in exps]\n        if rng is None:\n            idx = max(range(n), key=lambda i: probs[i])\n        else:\n            r = rng.random()\n            acc = 0.0\n            idx = n - 1\n            for i, p in enumerate(probs):\n                acc += p\n                if r <= acc:\n                    idx = i\n                    break\n        choices.append(idx)\n        logprob += math.log(max(probs[idx], 1e-12))\n    return choices, logprob\n\n\nclass NeuralPolicy:\n    """Day-plan provider: heuristic base plan, strategic fields overridden by\n    the network. Plugs into HeuristicPolicy via its plan_provider seam.\n    Falls back to the pure heuristic plan when no weights are loaded."""\n\n    def __init__(self, layers, temperature=1.0, rng=None):\n        self.layers = layers\n        self.temperature = temperature\n        self.rng = rng\n        self.last_decision = None  # (features, masks, choices, logprob, value)\n\n    def make_plan(self, view, memory):\n        plan = planner.make_day_plan(view, memory)\n        if self.layers is None:\n            return plan\n        x = features.encode(view, memory)\n        head_masks = features.masks(view)\n        logits, value = forward(self.layers, x)\n        choices, logprob = choose(\n            logits, head_masks, rng=self.rng, temperature=self.temperature\n        )\n        self.last_decision = (x, head_masks, choices, logprob, value)\n        return features.apply_to_plan(plan, choices, view)\n'),
